class ClickableThumbnail(QLabel):
    """Clickable Thumbnail Widget - A QLabel that emits signals when clicked"""
    
    clicked = pyqtSignal(int)  # row index
    
    def __init__(self, row_index: int, parent=None):
        """Initialize clickable thumbnail"""
        super().__init__(parent)
        
        self.row_index = row_index
        self.metadata = None  # Will be set when added to results
        self.setAlignment(Qt.AlignCenter)
        self.setStyleSheet("border: 1px solid #ccc; background-color: white;")
        self.setCursor(Qt.PointingHandCursor)
        self.setMouseTracking(True)
    
    def set_metadata(self, metadata: KeyframeMetadata):
        """Set metadata for this thumbnail"""
        self.metadata = metadata
    
    def mousePressEvent(self, event):
        """Handle mouse press event"""
        print(f"ClickableThumbnail mouse clicked: {event.button()}")
        
        if event.button() == Qt.LeftButton:
            self.clicked.emit(self.row_index)
        elif event.button() == Qt.RightButton and self.metadata:
            print("Right click detected on ClickableThumbnail, showing context menu...")
            self._show_context_menu(event.globalPos())
        super().mousePressEvent(event)
    
    def _show_context_menu(self, pos):
        """Show context menu with frame options"""
        try:
            from PyQt5.QtWidgets import QMenu, QAction
            
            menu = QMenu(self)
            
            # Add actions for surrounding frames
            action_show_surround = QAction("Nearby Frames", self)
            action_add_surround_to_csv = QAction("Add nearby frames to CSV", self)
            
            menu.addAction(action_show_surround)
            menu.addAction(action_add_surround_to_csv)
            
            # Connect actions
            action_show_surround.triggered.connect(
                lambda: self._handle_show_surrounding_frames()
            )
            action_add_surround_to_csv.triggered.connect(
                lambda: self._handle_add_surrounding_to_csv()
            )
            
            # Show menu
            menu.exec_(pos)
            print("Context menu shown successfully!")
            
        except Exception as e:
            print(f"Error showing context menu: {e}")
            import traceback
            traceback.print_exc()
    
    def _handle_show_surrounding_frames(self):
        """Handle showing surrounding frames"""
        try:
            # Debug: Print metadata info
            print(f"Metadata folder_name: '{self.metadata.folder_name}'")
            print(f"Metadata image_name: '{self.metadata.image_name}'")
            print(f"Metadata frame_id: {self.metadata.frame_id}")
            
            # Find the parent result display widget
            parent_widget = self.parent()
            while parent_widget and not hasattr(parent_widget, 'system'):
                parent_widget = parent_widget.parent()
            
            if parent_widget and hasattr(parent_widget, 'system'):
                parent_widget.show_surrounding_frames(self.metadata)
            else:
                from PyQt5.QtWidgets import QMessageBox
                QMessageBox.warning(self, "Lỗi", "Không tìm thấy hệ thống cha")
                
        except Exception as e:
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.critical(self, "Lỗi", f"Không thể hiển thị frame lân cận: {e}")
            print(f"Error in _handle_show_surrounding_frames: {e}")
            import traceback
            traceback.print_exc()
    
    def _handle_add_surrounding_to_csv(self):
        """Handle adding surrounding frames to CSV"""
        try:
            # Find the parent result display widget
            parent_widget = self.parent()
            while parent_widget and not hasattr(parent_widget, 'system'):
                parent_widget = parent_widget.parent()
            
            if parent_widget and hasattr(parent_widget, 'system'):
                parent_widget.add_surrounding_frames_to_csv(self.metadata)
            else:
                from PyQt5.QtWidgets import QMessageBox
                QMessageBox.warning(self, "Lỗi", "Không tìm thấy hệ thống cha")
                
        except Exception as e:
            from PyQt5.QtWidgets import QMessageBox
            QMessageBox.critical(self, "Lỗi", f"Không thể thêm frame lân cận vào CSV: {e}")
    
    def enterEvent(self, event):
        """Handle mouse enter event - add hover effect"""
        self.setStyleSheet("border: 2px solid #1F6FEB; background-color: #EAF3FF;")
        super().enterEvent(event)
    
    def leaveEvent(self, event):
        """Handle mouse leave event - remove hover effect"""
        self.setStyleSheet("border: 1px solid #ccc; background-color: white;")
        super().leaveEvent(event)


class ZoomableImageWidget(QWidget):
    """Zoomable Image Display Widget - Displays images with zoom capabilities"""
    
    def __init__(self, parent=None):
        """Initialize zoomable image widget"""
        super().__init__(parent)
        
        self.scale_factor = 1.0
        self.min_scale = 0.1
        self.max_scale = 5.0
        self.scale_step = 0.1
        
        self.original_pixmap = None
        self.scaled_pixmap = None
        
        self._setup_ui()
    
    def _setup_ui(self):
        """Setup the zoomable image UI"""
        layout = QVBoxLayout(self)
        layout.setContentsMargins(0, 0, 0, 0)
        
        # Control buttons
        controls_layout = QHBoxLayout()
        
        self.zoom_in_btn = QPushButton("+")
        self.zoom_in_btn.setMaximumSize(40, 30)
        self.zoom_in_btn.setToolTip("Zoom In")
        self.zoom_in_btn.clicked.connect(self.zoom_in)
        
        self.zoom_out_btn = QPushButton("-")
        self.zoom_out_btn.setMaximumSize(40, 30)
        self.zoom_out_btn.setToolTip("Zoom Out")
        self.zoom_out_btn.clicked.connect(self.zoom_out)
        
        self.fit_btn = QPushButton("Fit")
        self.fit_btn.setMaximumSize(40, 30)
        self.fit_btn.setToolTip("Fit to Window")
        self.fit_btn.clicked.connect(self.fit_to_window)
        
        self.actual_size_btn = QPushButton("1:1")
        self.actual_size_btn.setMaximumSize(60, 30)
        self.actual_size_btn.setToolTip("Actual Size")
        self.actual_size_btn.clicked.connect(self.actual_size)
        
        self.zoom_label = QLabel("100%")
        self.zoom_label.setMinimumWidth(50)
        self.zoom_label.setAlignment(Qt.AlignCenter)
        
        controls_layout.addWidget(self.zoom_in_btn)
        controls_layout.addWidget(self.zoom_out_btn)
        controls_layout.addWidget(self.fit_btn)
        controls_layout.addWidget(self.actual_size_btn)
        controls_layout.addWidget(self.zoom_label)
        controls_layout.addStretch()
        
        # Scrollable image area
        self.scroll_area = QScrollArea()
        self.scroll_area.setAlignment(Qt.AlignCenter)
        self.scroll_area.setStyleSheet("QScrollArea { border: 1px solid #ccc; background-color: #f0f0f0; }")
        
        self.image_label = QLabel()
        self.image_label.setAlignment(Qt.AlignCenter)
        self.image_label.setStyleSheet("background-color: white;")
        self.image_label.setText("No image loaded")
        
        self.scroll_area.setWidget(self.image_label)
        self.scroll_area.setWidgetResizable(True)
        
        # Enable mouse wheel events
        self.scroll_area.wheelEvent = self._wheel_event
        
        layout.addLayout(controls_layout)
        layout.addWidget(self.scroll_area)
    
    def set_image(self, pixmap: QPixmap):
        """Set image to display"""
        if pixmap and not pixmap.isNull():
            self.original_pixmap = pixmap
            self.scale_factor = 1.0
            self._update_image()
            self.fit_to_window()
        else:
            self.clear_image()
    
    def clear_image(self):
        """Clear the displayed image"""
        self.original_pixmap = None
        self.scaled_pixmap = None
        self.scale_factor = 1.0
        self.image_label.clear()
        self.image_label.setText("No image loaded")
        self._update_zoom_label()
    
    def zoom_in(self):
        """Zoom in the image"""
        if self.original_pixmap:
            new_scale = min(self.scale_factor + self.scale_step, self.max_scale)
            if new_scale != self.scale_factor:
                self.scale_factor = new_scale
                self._update_image()
    
    def zoom_out(self):
        """Zoom out the image"""
        if self.original_pixmap:
            new_scale = max(self.scale_factor - self.scale_step, self.min_scale)
            if new_scale != self.scale_factor:
                self.scale_factor = new_scale
                self._update_image()
    
    def fit_to_window(self):
        """Fit image to window size"""
        if not self.original_pixmap:
            return
        
        available_size = self.scroll_area.size()
        available_size.setWidth(available_size.width() - 20)
        available_size.setHeight(available_size.height() - 20)
        
        image_size = self.original_pixmap.size()
        scale_x = available_size.width() / image_size.width()
        scale_y = available_size.height() / image_size.height()
        
        self.scale_factor = min(scale_x, scale_y, 1.0)
        self.scale_factor = max(self.scale_factor, self.min_scale)
        
        self._update_image()
    
    def actual_size(self):
        """Show image at actual size (100%)"""
        if self.original_pixmap:
            self.scale_factor = 1.0
            self._update_image()
    
    def _update_image(self):
        """Update the displayed image with current scale"""
        if not self.original_pixmap:
            return
        
        new_size = self.original_pixmap.size() * self.scale_factor
        
        self.scaled_pixmap = self.original_pixmap.scaled(
            new_size,
            Qt.KeepAspectRatio,
            Qt.SmoothTransformation
        )
        
        self.image_label.setPixmap(self.scaled_pixmap)
        self.image_label.resize(self.scaled_pixmap.size())
        
        self._update_zoom_label()
    
    def _update_zoom_label(self):
        """Update the zoom percentage label"""
        percentage = int(self.scale_factor * 100)
        self.zoom_label.setText(f"{percentage}%")
    
    def _wheel_event(self, event):
        """Handle mouse wheel events for zooming"""
        if not self.original_pixmap:
            return
        
        delta = event.angleDelta().y()
        
        if delta > 0:
            self.zoom_in()
        else:
            self.zoom_out()
        
        event.accept()


class ImageViewerDialog(QDialog):
    """Full Size Image Viewer Dialog with zoom capabilities"""
    
    def __init__(self, frame_data, parent=None):
        """Initialize the image viewer dialog
        
        Args:
            frame_data: KeyframeMetadata object containing frame information
            parent: Parent widget
        """
        super().__init__(parent)
        self.frame_data = frame_data
        self.parent_gui = parent
        
        self.setWindowTitle(f"Image Viewer - {frame_data.image_name}")
        self.setMinimumSize(800, 600)
        self.resize(1000, 800)
        
        # Position the dialog lower on screen
        if parent:
            parent_geometry = parent.geometry()
            x = parent_geometry.x() + (parent_geometry.width() - 1000) // 2
            # Move dialog down by adding offset to y position
            y = parent_geometry.y() + (parent_geometry.height() - 800) // 2 + 100  # Added +100 offset
            # Ensure dialog doesn't go below screen
            screen = QApplication.desktop().screenGeometry()
            if y + 800 > screen.height():
                y = screen.height() - 800 - 50  # Leave 50px margin from bottom
            self.move(x, y)
        
        self._setup_ui()
        self._load_image()
        
        # Enable keyboard shortcuts
        self.setFocusPolicy(Qt.StrongFocus)
    
    def _setup_ui(self):
        """Setup the image viewer UI"""
        layout = QVBoxLayout(self)
        layout.setContentsMargins(10, 10, 10, 10)
        
        # Title bar with frame info
        title_layout = QHBoxLayout()
        
        title_label = QLabel(f"{self.frame_data.image_name} - Frame #{self.frame_data.frame_id}")
        title_label.setStyleSheet("""
            font-size: 16px; 
            font-weight: bold; 
            color: #333; 
            padding: 5px;
            background-color: #f0f0f0;
            border-radius: 5px;
        """)
        title_layout.addWidget(title_label)
        
        # Video info
        video_label = QLabel(f"{self.frame_data.folder_name}")
        video_label.setStyleSheet("""
            font-size: 14px; 
            color: #666; 
            padding: 5px;
            background-color: #f8f8f8;
            border-radius: 5px;
        """)
        title_layout.addWidget(video_label)
        
        title_layout.addStretch()
        
        # Close button
        close_btn = QPushButton("Close")
        close_btn.setStyleSheet("""
            QPushButton {
                background-color: white;
                color: #1F2937;
                border: 1px solid #A9C7F5;
                padding: 8px 16px;
                border-radius: 6px;
                font-weight: bold;
            }
            QPushButton:hover {
                background-color: #EAF3FF;
                border-color: #1F6FEB;
            }
        """)
        close_btn.clicked.connect(self.close)
        title_layout.addWidget(close_btn)
        
        layout.addLayout(title_layout)
        
        # Zoomable image widget
        self.image_widget = ZoomableImageWidget(self)
        layout.addWidget(self.image_widget)
        
        # Status bar
        status_layout = QHBoxLayout()
        
        self.status_label = QLabel("Loading image...")
        self.status_label.setStyleSheet("color: #666; font-size: 12px; padding: 5px;")
        status_layout.addWidget(self.status_label)
        
        status_layout.addStretch()
        
        # Instructions
        instructions = QLabel("Scroll to zoom. Use +/- buttons or Fit.")
        instructions.setStyleSheet("color: #999; font-size: 11px; padding: 5px;")
        status_layout.addWidget(instructions)
        
        layout.addLayout(status_layout)
    
    def _load_image(self):
        """Load and display the full-size image"""
        try:
            # Try to get image from parent GUI if available
            if hasattr(self.parent_gui, '_get_image_from_unified_or_file'):
                pixmap = self.parent_gui._get_image_from_unified_or_file(self.frame_data)
            else:
                # Fallback: load directly from file
                image_path = Path(self.frame_data.folder_name) / self.frame_data.image_name
                if image_path.exists():
                    pixmap = QPixmap(str(image_path))
                else:
                    pixmap = None
            
            if pixmap and not pixmap.isNull():
                self.image_widget.set_image(pixmap)
                # Update status with image dimensions
                size_info = f"Image loaded: {pixmap.width()} × {pixmap.height()} pixels"
                self.status_label.setText(size_info)
                self.status_label.setStyleSheet("color: #28a745; font-size: 12px; padding: 5px;")
            else:
                # Show error message
                self.status_label.setText("Failed to load image")
                self.status_label.setStyleSheet("color: #dc3545; font-size: 12px; padding: 5px;")
                
                # Show placeholder in image widget
                error_pixmap = QPixmap(400, 300)
                error_pixmap.fill(QColor("#f8f9fa"))
                painter = QPainter(error_pixmap)
                painter.setPen(QColor("#6c757d"))
                painter.setFont(QFont("Arial", 16))
                painter.drawText(error_pixmap.rect(), Qt.AlignCenter, "Image not found")
                painter.end()
                
                self.image_widget.set_image(error_pixmap)
                
        except Exception as e:
            self.status_label.setText(f"Error loading image: {str(e)}")
            self.status_label.setStyleSheet("color: #dc3545; font-size: 12px; padding: 5px;")
            print(f"Error loading image in viewer: {e}")
    
    def keyPressEvent(self, event):
        """Handle keyboard shortcuts"""
        if event.key() == Qt.Key_Escape:
            self.close()
        elif event.key() == Qt.Key_Plus or event.key() == Qt.Key_Equal:
            self.image_widget.zoom_in()
        elif event.key() == Qt.Key_Minus:
            self.image_widget.zoom_out()
        elif event.key() == Qt.Key_0:
            self.image_widget.fit_to_window()
        else:
            super().keyPressEvent(event)


class InteractiveThumbnail(QLabel):
    """Enhanced Interactive Thumbnail - Advanced thumbnail widget with hover effects"""
    
    clicked = pyqtSignal(object)  # metadata
    double_clicked = pyqtSignal(object)  # metadata
    context_menu_requested = pyqtSignal(object, QPoint)  # metadata, position
    
    def __init__(self, metadata: KeyframeMetadata, thumbnail_size: int = 350, parent=None):
        """Initialize interactive thumbnail"""
        super().__init__(parent)
        
        self.metadata = metadata
        self.thumbnail_size = thumbnail_size
        self.is_selected = False
        self.hover_animation = None
        
        self._setup_thumbnail()
        self._setup_interactions()
        
        self.setFixedSize(thumbnail_size, int(thumbnail_size * 0.75))
        self.setAlignment(Qt.AlignCenter)
        self.setStyleSheet("""
            QLabel {
                border: 2px solid #E0E0E0;
                border-radius: 8px;
                background-color: white;
            }
            QLabel:hover {
                border-color: #1F6FEB;
                background-color: #EAF3FF;
            }
        """)
    
    def _setup_thumbnail(self):
        """Setup thumbnail image"""
        try:
            if os.path.exists(self.metadata.file_path):
                pixmap = QPixmap(self.metadata.file_path)
                if not pixmap.isNull():
                    scaled_pixmap = pixmap.scaledToWidth(
                        self.thumbnail_size - 10,
                        Qt.SmoothTransformation
                    )
                    self.setPixmap(scaled_pixmap)
                else:
                    self._set_placeholder_image("Invalid Image")
            else:
                self._set_placeholder_image("Image Not Found")
                
        except Exception as e:
            self._set_placeholder_image(f"Error: {str(e)}")
    
    def _set_placeholder_image(self, text: str):
        """Set placeholder image with text"""
        placeholder = QPixmap(self.thumbnail_size - 10, int(self.thumbnail_size * 0.75) - 10)
        placeholder.fill(QColor("#F5F5F5"))
        
        painter = QPainter(placeholder)
        painter.setPen(QPen(QColor("#757575")))
        painter.drawText(placeholder.rect(), Qt.AlignCenter, text)
        painter.end()
        
        self.setPixmap(placeholder)
    
    def _setup_interactions(self):
        """Setup mouse interactions"""
        self.setMouseTracking(True)
        self.setCursor(QCursor(Qt.PointingHandCursor))
    
    def mousePressEvent(self, event):
        """Handle mouse press events"""
        if event.button() == Qt.LeftButton:
            self.clicked.emit(self.metadata)
        elif event.button() == Qt.RightButton:
            self._show_context_menu(event.globalPos())
        super().mousePressEvent(event)
    
    def _show_context_menu(self, pos):
        """Show context menu with frame options"""
        try:
            from PyQt5.QtWidgets import QMenu, QAction
            
            menu = QMenu(self)
            
            # Add actions for surrounding frames
            action_show_surround = QAction("Nearby Frames", self)
            action_add_surround_to_csv = QAction("Add nearby frames to CSV", self)
            
            menu.addAction(action_show_surround)
            menu.addAction(action_add_surround_to_csv)
            
            # Connect actions
            action_show_surround.triggered.connect(
                lambda: self._handle_show_surrounding_frames()
            )
            action_add_surround_to_csv.triggered.connect(
                lambda: self._handle_add_surrounding_to_csv()
            )
            
            # Show menu
            menu.exec_(pos)
            
        except Exception as e:
            print(f"Error showing context menu: {e}")
            import traceback
            traceback.print_exc()
    
    def _handle_show_surrounding_frames(self):
        """Handle showing surrounding frames"""
        try:
            # Find the parent result display widget
            parent_widget = self.parent()
            while parent_widget and not hasattr(parent_widget, 'system'):
                parent_widget = parent_widget.parent()
            
            if parent_widget and hasattr(parent_widget, 'system'):
                parent_widget.show_surrounding_frames(self.metadata)
            else:
                QMessageBox.warning(self, "Lỗi", "Không tìm thấy hệ thống cha")
                
        except Exception as e:
            QMessageBox.critical(self, "Lỗi", f"Không thể hiển thị frame lân cận: {e}")
    
    def _handle_add_surrounding_to_csv(self):
        """Handle adding surrounding frames to CSV"""
        try:
            # Find the parent result display widget
            parent_widget = self.parent()
            while parent_widget and not hasattr(parent_widget, 'system'):
                parent_widget = parent_widget.parent()
            
            if parent_widget and hasattr(parent_widget, 'system'):
                parent_widget.add_surrounding_frames_to_csv(self.metadata)
            else:
                QMessageBox.warning(self, "Lỗi", "Không tìm thấy hệ thống cha")
                
        except Exception as e:
            QMessageBox.critical(self, "Lỗi", f"Không thể thêm frame lân cận vào CSV: {e}")
    
    def mouseDoubleClickEvent(self, event):
        """Handle double click events"""
        if event.button() == Qt.LeftButton:
            self.double_clicked.emit(self.metadata)
            self._show_image_dialog(self.metadata)
        super().mouseDoubleClickEvent(event)
    
    def enterEvent(self, event):
        """Handle mouse enter (hover start)"""
        self._animate_hover(True)
        super().enterEvent(event)
    
    def leaveEvent(self, event):
        """Handle mouse leave (hover end)"""
        self._animate_hover(False)
        super().leaveEvent(event)
    
    def _animate_hover(self, hover_in: bool):
        """Animate hover effect"""
        if hasattr(self, 'hover_animation') and self.hover_animation:
            self.hover_animation.stop()
        
        self.hover_animation = QPropertyAnimation(self, b"geometry")
        self.hover_animation.setDuration(200)
        self.hover_animation.setEasingCurve(QEasingCurve.OutCubic)
        
        start_rect = self.geometry()
        if hover_in:
            end_rect = QRect(
                start_rect.x() - 2,
                start_rect.y() - 2,
                start_rect.width() + 4,
                start_rect.height() + 4
            )
        else:
            end_rect = start_rect
        
        self.hover_animation.setStartValue(start_rect)
        self.hover_animation.setEndValue(end_rect)
        self.hover_animation.start()
    
    def set_selected(self, selected: bool):
        """Set selection state"""
        self.is_selected = selected
        if selected:
            self.setStyleSheet("""
                QLabel {
                    border: 3px solid #1F6FEB;
                    border-radius: 8px;
                    background-color: #EAF3FF;
                }
            """)
        else:
            self.setStyleSheet("""
                QLabel {
                    border: 2px solid #E0E0E0;
                    border-radius: 8px;
                    background-color: white;
                }
                QLabel:hover {
                    border-color: #1F6FEB;
                    background-color: #EAF3FF;
                }
            """)
    
    def _show_image_dialog(self, metadata: KeyframeMetadata):
        """Show full size image dialog"""
        dialog = QDialog(self)
        dialog.setWindowTitle(f"{metadata.folder_name} - {metadata.image_name}")
        dialog.setModal(True)
        
        layout = QVBoxLayout(dialog)
        
        image_label = QLabel()
        if os.path.exists(metadata.file_path):
            pixmap = QPixmap(metadata.file_path)
            if not pixmap.isNull():
                screen_size = QApplication.desktop().screenGeometry()
                max_size = min(screen_size.width() * 0.8, screen_size.height() * 0.8)
                scaled_pixmap = pixmap.scaled(
                    int(max_size), int(max_size),
                    Qt.KeepAspectRatio, Qt.SmoothTransformation
                )
                image_label.setPixmap(scaled_pixmap)
            else:
                image_label.setText("Failed to load image")
        else:
            image_label.setText("Image file not found")
        
        image_label.setAlignment(Qt.AlignCenter)
        layout.addWidget(image_label)
        
        info_text = f"Folder: {metadata.folder_name}\n"
        info_text += f"Image: {metadata.image_name}\n"
        info_text += f"Frame ID: {metadata.frame_id}\n"
        info_text += f"Path: {metadata.file_path}"
        
        info_label = QLabel(info_text)
        info_label.setAlignment(Qt.AlignCenter)
        layout.addWidget(info_label)
        
        dialog.resize(800, 600)
        dialog.exec_()

