class ResultDisplayWidget(QWidget):
    """Advanced Result Display Widget - Displays search results in a split view"""
    
    selection_changed = pyqtSignal(list)  # selected metadata
    
    def __init__(self, parent=None, system=None):
        super().__init__(parent)
        self.selected_items = []
        self.results = []
        self.system = system
        self.logger = system.logger if system else None
        
        # Initialize search index variables
        self.video_info = {}
        self.last_search_result = None  # Store last search result for CSV export
        
        # PATCH: Store system reference globally for recovery
        if system:
            app = QApplication.instance()
            if app:
                app.retrieval_system = system
        
        self._setup_ui()
    
    def _recover_system_reference(self) -> bool:
        """Multi-strategy system reference recovery"""
        if hasattr(self, 'system') and self.system:
            return True
            
        # Strategy 1: From QApplication
        app = QApplication.instance()
        if app and hasattr(app, 'retrieval_system') and app.retrieval_system:
            self.system = app.retrieval_system
            return True
        
        # Strategy 2: From parent widgets
        parent = self.parent()
        while parent:
            if hasattr(parent, 'system') and parent.system:
                self.system = parent.system
                return True
            parent = parent.parent()
        
        # Strategy 3: Try to create minimal system for .rvdb access
        try:
            from system import EnhancedRetrievalSystem
            from utils import Logger
            self.system = EnhancedRetrievalSystem()
            # Don't call full initialize, just set up basic components
            self.system.logger = Logger()
            return True
        except Exception as e:
            pass
            
        return False

    # ==============================================
    # SEARCH INDEX FUNCTIONALITY METHODS
    # ==============================================
    
    def _browse_video_folder(self):
        """Browse for video folder and scan for videos"""
        folder_path = QFileDialog.getExistingDirectory(
            self, "Select Video Folder", "", 
            QFileDialog.ShowDirsOnly | QFileDialog.DontResolveSymlinks
        )
        
        if folder_path:
            self.video_folder_path.setText(folder_path)
            self.search_status.setText("Scanning videos...")
            self.video_info = {}  # Initialize video info dict
            
            # Scan videos synchronously for now (can be made async later)
            self._scan_videos_sync(folder_path)
    
    def _scan_videos_sync(self, folder_path):
        """Scan videos synchronously"""
        try:
            from pathlib import Path
            from PyQt5.QtWidgets import QApplication
            import cv2
            
            supported_formats = ['.mp4', '.avi', '.mkv', '.mov', '.wmv', '.flv', '.webm', '.m4v']
            video_files = []
            
            # Find all video files
            folder_path_obj = Path(folder_path)
            for file_path in folder_path_obj.rglob('*'):
                if file_path.suffix.lower() in supported_formats:
                    video_files.append(file_path)
            
            print(f"Found {len(video_files)} video files")
            self.search_status.setText(f"Found {len(video_files)} video files, extracting metadata...")
            
            # Update video list immediately
            self._update_video_list_gui(video_files)
            
            # Extract metadata for each video
            for i, video_path in enumerate(video_files):
                try:
                    self.search_status.setText(f"Processing video {i+1}/{len(video_files)}: {video_path.name}")
                    
                    # Process events to keep GUI responsive
                    QApplication.processEvents()
                    
                    metadata = self._extract_video_metadata(video_path)
                    if metadata:
                        self.video_info[video_path.name] = {
                            'path': str(video_path),
                            'metadata': metadata
                        }
                        
                        # Update GUI with metadata
                        self._update_video_metadata_gui(video_path.name, metadata['duration'], metadata['fps'])
                        
                except Exception as e:
                    print(f"Error processing {video_path.name}: {e}")
                    # Update table with error status
                    self._update_video_metadata_gui(video_path.name, -1, -1)
                    continue
            
            # Final status update
            self.search_status.setText(f"Processing complete! Found {len(self.video_info)} valid videos")
            
        except Exception as e:
            self.search_status.setText(f"Failed to scan videos: {str(e)}")
            print(f"Error in _scan_videos_sync: {e}")
            import traceback
            import traceback
            traceback.print_exc()
    
    def _update_video_list_gui(self, video_files):
        """Update the video list widget with found videos"""
        self.video_list_widget.setRowCount(0)
        
        for video_path in sorted(video_files):
            row_position = self.video_list_widget.rowCount()
            self.video_list_widget.insertRow(row_position)
            
            # Video name
            self.video_list_widget.setItem(row_position, 0, QTableWidgetItem(video_path.name))
            
            # Placeholder for duration and FPS (will be filled by metadata extraction)
            self.video_list_widget.setItem(row_position, 1, QTableWidgetItem("Loading..."))
            self.video_list_widget.setItem(row_position, 2, QTableWidgetItem("Loading..."))
    
    def _extract_video_metadata(self, video_path):
        """Extract metadata from video file using OpenCV"""
        try:
            import cv2  # Import cv2 here
            cap = cv2.VideoCapture(str(video_path))
            
            if not cap.isOpened():
                return None
            
            # Get video properties
            fps = cap.get(cv2.CAP_PROP_FPS)
            frame_count = int(cap.get(cv2.CAP_PROP_FRAME_COUNT))
            width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))
            height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))
            
            # Calculate duration
            duration = frame_count / fps if fps > 0 else 0
            
            cap.release()
            
            # Update GUI with extracted metadata
            QTimer.singleShot(0, lambda: self._update_video_metadata_gui(video_path.name, duration, fps))
            
            return {
                'fps': fps,
                'frame_count': frame_count,
                'width': width,
                'height': height,
                'duration': duration,
                'file_size': video_path.stat().st_size
            }
            
        except Exception as e:
            print(f"Error extracting metadata from {video_path}: {e}")
            return None
    
    def _update_video_metadata_gui(self, video_name, duration, fps):
        """Update GUI with video metadata"""
        try:
            for row in range(self.video_list_widget.rowCount()):
                item = self.video_list_widget.item(row, 0)
                if item and item.text() == video_name:
                    # Update duration
                    if duration >= 0:
                        duration_text = f"{duration:.1f}s"
                    else:
                        duration_text = "Error"
                    self.video_list_widget.setItem(row, 1, QTableWidgetItem(duration_text))
                    
                    # Update FPS
                    if fps >= 0:
                        fps_text = f"{fps:.1f}"
                    else:
                        fps_text = "Error"
                    self.video_list_widget.setItem(row, 2, QTableWidgetItem(fps_text))
                    break
        except Exception as e:
            print(f"Error updating video metadata GUI: {e}")
    
    def _on_video_selection_changed(self):
        """Handle video selection change"""
        try:
            current_row = self.video_list_widget.currentRow()
            if current_row >= 0:
                video_name_item = self.video_list_widget.item(current_row, 0)
                if video_name_item:
                    self.video_name_input.setText(video_name_item.text())
        except Exception as e:
            print(f"Error in video selection: {e}")
    
    def _auto_fill_video_name(self):
        """Auto-fill video name from current selection"""
        try:
            current_row = self.video_list_widget.currentRow()
            if current_row >= 0:
                video_name_item = self.video_list_widget.item(current_row, 0)
                if video_name_item:
                    self.video_name_input.setText(video_name_item.text())
            else:
                from PyQt5.QtWidgets import QMessageBox
                QMessageBox.warning(self, "No Selection", "Please select a video from the list first")
        except Exception as e:
            print(f"Error in auto fill: {e}")
    
    def _search_frame_index(self):
        """Search for frame index based on video name and time"""
        try:
            from PyQt5.QtWidgets import QMessageBox, QApplication
            
            video_name = self.video_name_input.text().strip()
            time_str = self.time_input.text().strip()
            
            # Validate inputs
            if not video_name:
                QMessageBox.critical(self, "Error", "Please enter a video name")
                return
            
            if not time_str:
                QMessageBox.critical(self, "Error", "Please enter a time in seconds")
                return
            
            try:
                time_seconds = float(time_str)
                if time_seconds < 0:
                    QMessageBox.critical(self, "Error", "Time must be non-negative")
                    return
            except ValueError:
                QMessageBox.critical(self, "Error", "Please enter a valid number for time")
                return
            
            # Find video in our metadata
            if not hasattr(self, 'video_info') or video_name not in self.video_info:
                QMessageBox.critical(self, "Error", f"Video '{video_name}' not found in scanned videos.\nPlease scan videos first.")
                return
            
            video_data = self.video_info[video_name]
            metadata = video_data['metadata']
            
            # Calculate frame index
            frame_index, calc_info = self._calculate_frame_index(time_seconds, metadata)
            
            # Display results
            self._display_search_results(video_name, time_seconds, frame_index, calc_info, metadata)
            
        except Exception as e:
            print(f"Error in search frame index: {e}")
            try:
                from PyQt5.QtWidgets import QMessageBox
                QMessageBox.critical(self, "Error", f"Search failed: {str(e)}")
            except:
                self.search_status.setText(f"Search failed: {str(e)}")
    
    def _calculate_frame_index(self, time_seconds, metadata):
        """Calculate frame index from time and return additional info"""
        fps = metadata['fps']
        frame_count = metadata['frame_count']
        duration = metadata['duration']
        
        # Calculate frame index (0-based)
        frame_index = int(time_seconds * fps)
        
        # Validate frame index is within bounds
        is_clamped = False
        if frame_index >= frame_count:
            frame_index = frame_count - 1  # Use last frame
            actual_time = frame_index / fps
            is_clamped = True
        else:
            actual_time = frame_index / fps
        
        return frame_index, {
            'actual_time': actual_time,
            'fps': fps,
            'duration': duration,
            'frame_count': frame_count,
            'is_clamped': is_clamped
        }
    
    def _display_search_results(self, video_name, requested_time, frame_index, calc_info, metadata):
        """Display search results in the results text area"""
        try:
            # Clear previous results
            self.search_results_text.clear()
            
            # Format simple results - only frame index
            results = []
            results.append(f"Video: {video_name}")
            results.append(f"Time: {calc_info['actual_time']:.3f}s")
            results.append(f"Frame Index: {frame_index}")
            
            if calc_info['is_clamped']:
                results.append("⚠️ Time exceeds video duration")
            
            # Display results
            results_text = "\n".join(results)
            self.search_results_text.setPlainText(results_text)
            
            # Store search result for CSV export
            self.last_search_result = {
                'video_name': video_name,
                'time': calc_info['actual_time'],
                'frame_index': frame_index,
                'video_path': self.video_info[video_name]['path']
            }
            
            # Enable Add to CSV button
            if hasattr(self, 'add_to_csv_btn'):
                self.add_to_csv_btn.setEnabled(True)
            
            # Update status
            self.search_status.setText(f"Frame Index: {frame_index}")
            
            # Copy result to clipboard for convenience
            try:
                from PyQt5.QtWidgets import QApplication
                clipboard = QApplication.clipboard()
                clipboard.setText(str(frame_index))
                self.search_status.setText(f"Frame Index: {frame_index} (copied to clipboard)")
            except Exception as clipboard_error:
                print(f"Clipboard error: {clipboard_error}")
                # Don't fail the whole operation if clipboard fails
                
        except Exception as e:
            print(f"Error displaying search results: {e}")
            self.search_status.setText(f"Error displaying results: {str(e)}")
    
    def _add_search_result_to_csv(self):
        """Add the last search result to CSV list"""
        try:
            from PyQt5.QtWidgets import QMessageBox, QTableWidgetItem, QCheckBox
            from PyQt5.QtCore import Qt
            
            # Check if we have a search result
            if not hasattr(self, 'last_search_result') or self.last_search_result is None:
                QMessageBox.warning(self, "No Result", "Please perform a search first")
                return
            
            result = self.last_search_result
            
            # Create frame description for CSV list
            frame_description = f"{result['video_name']} | Time: {result['time']:.3f}s | Frame: {result['frame_index']}"
            
            # Check if this entry already exists in CSV list
            for row in range(self.csv_results_list.rowCount()):
                existing_frame = self.csv_results_list.item(row, 1)
                if existing_frame and existing_frame.text() == frame_description:
                    QMessageBox.information(self, "Already Added", 
                                          f"This result is already in the CSV list:\n{frame_description}")
                    return
            
            # Add to CSV table
            row_count = self.csv_results_list.rowCount()
            self.csv_results_list.insertRow(row_count)
            
            # Add checkbox in first column
            checkbox_item = QTableWidgetItem("")
            checkbox_item.setFlags(Qt.ItemIsUserCheckable | Qt.ItemIsEnabled)
            checkbox_item.setCheckState(Qt.Unchecked)
            self.csv_results_list.setItem(row_count, 0, checkbox_item)
            
            # Add frame description in second column
            frame_item = QTableWidgetItem(frame_description)
            self.csv_results_list.setItem(row_count, 1, frame_item)
            
            # Add status in third column
            status_item = QTableWidgetItem("Ready")
            self.csv_results_list.setItem(row_count, 2, status_item)
            
            # Update CSV tab title count
            self._update_csv_tab_title()
            
            # Update status
            self.search_status.setText(f"Added to CSV: {result['video_name']} at frame {result['frame_index']}")
            
            # Show success message
            QMessageBox.information(self, "Added to CSV", 
                                  f"Successfully added to CSV list:\n"
                                  f"Video: {result['video_name']}\n"
                                  f"Time: {result['time']:.3f}s\n"
                                  f"Frame Index: {result['frame_index']}")
            
        except Exception as e:
            print(f"Error adding to CSV: {e}")
            try:
                from PyQt5.QtWidgets import QMessageBox
                QMessageBox.critical(self, "Error", f"Failed to add to CSV: {str(e)}")
            except:
                self.search_status.setText(f"Error adding to CSV: {str(e)}")
    
