    def _update_system_info(self):
       """Update system information display"""
       if not hasattr(self, 'system_status_label'):
           self.system_status_label = QLabel("Not initialized")
       if not hasattr(self, 'index_status_label'):
           self.index_status_label = QLabel("No index loaded")
       if not hasattr(self, 'performance_label'):
           self.performance_label = QLabel("No data")

       if not self.system:
           self.system_status_label.setText("Not initialized")
           self.index_status_label.setText("No index loaded")
           self.performance_label.setText("No data")
           if hasattr(self, 'header_status_label'):
               self.header_status_label.setText("System: Not initialized | Index: Not loaded")
           return
       
       try:
           if hasattr(self.system, 'status') and self.system.status:
               status = self.system.status
               self.system_status_label.setText("Ready" if status.is_ready else "Not Ready")
               self.index_status_label.setText("Loaded" if status.index_loaded else "Not Loaded")
           else:
               has_index = hasattr(self.system, 'index') and self.system.index is not None
               self.system_status_label.setText("Ready" if has_index else "Not Ready")
               self.index_status_label.setText("Loaded" if has_index else "Not Loaded")
           
           self._refresh_stats()
           if hasattr(self, 'header_status_label'):
               self.header_status_label.setText(
                   f"System: {self.system_status_label.text()} | Index: {self.index_status_label.text()}"
               )
           
       except Exception as e:
           self.system_status_label.setText(f"Error: {str(e)}")
   
    def _refresh_stats(self):
       """Refresh system statistics"""
       if not self.system:
           return
       
       try:
           try:
               from unified_builder import get_runtime_system
               runtime_system = get_runtime_system(self.system)
           except Exception:
               runtime_system = self.system

           details = []
           faiss_retriever = getattr(runtime_system, 'faiss_retriever', None)
           faiss_index = getattr(faiss_retriever, 'index', None) if faiss_retriever else None
           if faiss_index is not None:
               total_vectors = getattr(faiss_index, 'ntotal', None)
               dimension = getattr(faiss_retriever, 'dimension', None)
               if total_vectors is not None:
                   details.append(f"{total_vectors} keyframes")
               if dimension is not None:
                   details.append(f"{dimension}d")

           active_encoder = getattr(getattr(runtime_system, 'active_query_encoder', None), 'model_path', None)
           if active_encoder:
               details.append(active_encoder)

           build_source = getattr(faiss_retriever, 'index_build_source', None) if faiss_retriever else None
           if build_source:
               details.append(build_source)

           detail_text = " | ".join(details) if details else "No data"
           self.performance_label.setText(detail_text)
           if hasattr(self, 'status_bar'):
               self.status_bar.showMessage(
                   f"{self.system_status_label.text()} | {self.index_status_label.text()} | {detail_text}"
               )
           
       except Exception as e:
           pass
   
    def _refresh_all(self):
       """Refresh all information"""
       self._update_system_info()
       self.status_bar.showMessage("Information refreshed")
   
