    def _update_confidence_badge(self, margin_info: Optional[Dict[str, Any]]):
        """Update confidence indicator badge based on margin between Rank 1 and Rank 2"""
        if not hasattr(self, 'confidence_badge'):
            return
        if not margin_info:
            self.confidence_badge.setVisible(False)
            return

        margin = margin_info.get("margin", 0.0)
        is_ambiguous = margin_info.get("is_ambiguous", False)

        if margin >= 0.12 and not is_ambiguous:
            self.confidence_badge.setText(f"🟢 High Confidence (Margin: {margin:.3f})")
            self.confidence_badge.setStyleSheet(
                "QLabel { background-color: #E6F4EA; color: #137333; border: 1px solid #CEEAD6; "
                "border-radius: 4px; padding: 4px 10px; font-weight: bold; font-size: 11px; }"
            )
        elif is_ambiguous or margin < 0.06:
            self.confidence_badge.setText(f"🟡 Ambiguous (Margin: {margin:.3f}) - Review Top 5")
            self.confidence_badge.setStyleSheet(
                "QLabel { background-color: #FEF7E0; color: #B06000; border: 1px solid #FEEFC3; "
                "border-radius: 4px; padding: 4px 10px; font-weight: bold; font-size: 11px; }"
            )
        else:
            self.confidence_badge.setText(f"🔵 Moderate (Margin: {margin:.3f})")
            self.confidence_badge.setStyleSheet(
                "QLabel { background-color: #E8F0FE; color: #1A73E8; border: 1px solid #D2E3FC; "
                "border-radius: 4px; padding: 4px 10px; font-weight: bold; font-size: 11px; }"
            )
        self.confidence_badge.setVisible(True)

    def _update_query_decomposition_strip(self, decomp):
        """Update query de-noising & decomposition strip with task type and core anchor"""
        if not hasattr(self, 'query_decomp_label'):
            return
        task_str = getattr(decomp.task_type, 'value', str(decomp.task_type))
        task_color = "#1A73E8" if task_str == "KIS" else ("#E37400" if task_str == "TRAKE" else "#A142F4")
        core_anchor = getattr(decomp, 'core_anchor', '')
        context = getattr(decomp, 'context_query', getattr(decomp, 'context', ''))
        noise = getattr(decomp, 'noise_phrases', [])

        text = (
            f"<span style='background-color:{task_color}; color:white; padding:2px 6px; border-radius:3px; font-weight:bold;'>"
            f"{task_str}</span> "
            f"<b>Core Anchor:</b> <span style='color:#185ABC;'>{core_anchor}</span>"
        )
        if context:
            text += f" | <b>Context:</b> <span style='color:#5F6368;'>{context}</span>"
        if noise:
            noise_str = ", ".join(noise)
            text += f" | <span style='color:#D93025; text-decoration:line-through;'>[Noise stripped: {noise_str}]</span>"

        self.query_decomp_label.setText(text)
        self.query_decomp_label.setVisible(True)

    def _copy_current_submission_to_clipboard(self):
        """Quick copy submission format (video_name, frame_id) for current result or rank 1"""
        target_result = None
        if hasattr(self, 'results_widget') and self.results_widget:
            curr_idx = self.results_widget.current_result_index
            if curr_idx is not None and 0 <= curr_idx < len(self.results_widget.results):
                target_result = self.results_widget.results[curr_idx]
            elif hasattr(self, 'current_results') and self.current_results:
                target_result = self.current_results[0]

        if not target_result:
            self.status_bar.showMessage("No result available to copy", 3000)
            return

        meta = target_result.metadata
        csv_row = f"{meta.folder_name},{meta.frame_id}"
        clipboard = QApplication.clipboard()
        clipboard.setText(csv_row)
        self.status_bar.showMessage(f"📋 Copied to Clipboard: {csv_row}", 4000)

    def _select_result_card_by_index(self, index: int):
        """Quick select result card 1 to 9"""
        if hasattr(self, 'results_widget') and self.results_widget:
            if 0 <= index < len(self.results_widget.result_cards):
                self.results_widget._select_result_card(index)
                res = self.results_widget.results[index]
                self.status_bar.showMessage(f"Selected Rank {index + 1}: {res.metadata.folder_name} (Frame {res.metadata.frame_id})", 3000)

    def _toggle_current_card_selection(self):
        """Toggle checkbox on currently selected card (Space hotkey)"""
        if hasattr(self, 'results_widget') and self.results_widget:
            curr_idx = self.results_widget.current_result_index
            if curr_idx is not None and 0 <= curr_idx < len(self.results_widget.result_checkboxes):
                cb = self.results_widget.result_checkboxes[curr_idx]
                cb.setChecked(not cb.isChecked())
                state_str = "Checked" if cb.isChecked() else "Unchecked"
                self.status_bar.showMessage(f"{state_str} Rank {curr_idx + 1}", 2000)

    def _open_surrounding_frames_for_current(self):
        """Open surrounding frames dialog for current card (F hotkey)"""
        if hasattr(self, 'results_widget') and self.results_widget:
            curr_idx = self.results_widget.current_result_index
            if curr_idx is not None and 0 <= curr_idx < len(self.results_widget.results):
                self.results_widget.show_surrounding_frames(self.results_widget.results[curr_idx].metadata)

    def _navigate_result_card(self, direction: int):
        """Navigate previous / next result card (Left / Right arrow hotkey)"""
        if hasattr(self, 'results_widget') and self.results_widget:
            cards = self.results_widget.result_cards
            if not cards:
                return
            curr_idx = self.results_widget.current_result_index
            if curr_idx is None:
                new_idx = 0
            else:
                new_idx = max(0, min(len(cards) - 1, curr_idx + direction))
            self._select_result_card_by_index(new_idx)

    def keyPressEvent(self, event):
        """Competition hotkeys for lightning-fast inspection"""
        focus_widget = QApplication.focusWidget()
        if isinstance(focus_widget, (QTextEdit, QLineEdit)):
            super().keyPressEvent(event)
            return

        key = event.key()
        modifiers = event.modifiers()

        # 1-9: Select result card 1 to 9
        if Qt.Key_1 <= key <= Qt.Key_9:
            index = key - Qt.Key_1
            self._select_result_card_by_index(index)
            event.accept()
            return

        # Space: Toggle checkbox on currently selected card
        elif key == Qt.Key_Space:
            self._toggle_current_card_selection()
            event.accept()
            return

        # F: View surrounding frames
        elif key == Qt.Key_F:
            self._open_surrounding_frames_for_current()
            event.accept()
            return

        # E or Ctrl+C: Quick copy submission format
        elif key == Qt.Key_E or (key == Qt.Key_C and (modifiers & Qt.ControlModifier)):
            self._copy_current_submission_to_clipboard()
            event.accept()
            return

        # Left / Right arrow navigation
        elif key == Qt.Key_Left:
            self._navigate_result_card(-1)
            event.accept()
            return
        elif key == Qt.Key_Right:
            self._navigate_result_card(1)
            event.accept()
            return

        super().keyPressEvent(event)

    def _get_image_from_unified_or_file(self, metadata) -> Optional[QPixmap]:
        """Get image from results_widget or direct file path fallback"""
        if hasattr(self, 'results_widget') and hasattr(self.results_widget, '_get_image_from_unified_or_file'):
            pix = self.results_widget._get_image_from_unified_or_file(metadata)
            if pix and not pix.isNull():
                return pix
        if hasattr(metadata, 'file_path') and metadata.file_path and os.path.exists(metadata.file_path):
            pix = QPixmap(metadata.file_path)
            if not pix.isNull():
                return pix
        return None

