    def _run_qa_search(self):
        """Execute candidate search for QA scene description"""
        query = self.qa_scene_input.text().strip()
        if not query:
            QMessageBox.warning(self, "Warning", "Vui lòng nhập mô tả cảnh để tìm keyframe.")
            return
        if not self.system or not self.system.status.is_ready:
            QMessageBox.warning(self, "Warning", "Hệ thống chưa sẵn sàng. Vui lòng chờ tải index.")
            return

        self.status_bar.showMessage(f"Searching QA candidates: {query}...", 3000)
        results = self.system.search(query, options=None)
        self.qa_candidate_results = results[:30]

        # Clear existing candidate widgets
        while self.qa_candidates_layout.count():
            item = self.qa_candidates_layout.takeAt(0)
            if item.widget():
                item.widget().deleteLater()

        for idx, res in enumerate(self.qa_candidate_results):
            meta = res.metadata
            card = QFrame()
            card.setFrameShape(QFrame.StyledPanel)
            card.setStyleSheet("QFrame { background-color: white; border: 1px solid #D0D7DE; border-radius: 4px; padding: 4px; } QFrame:hover { border: 2px solid #1F6FEB; background-color: #EAF3FF; }")
            card_layout = QHBoxLayout(card)
            card_layout.setContentsMargins(4, 4, 4, 4)
            card_layout.setSpacing(6)

            thumb = QLabel()
            thumb.setFixedSize(80, 60)
            thumb.setScaledContents(True)
            pix = self._get_image_from_unified_or_file(meta)
            if pix and not pix.isNull():
                thumb.setPixmap(pix.scaled(80, 60, Qt.KeepAspectRatio, Qt.SmoothTransformation))
            else:
                thumb.setText("No Img")
                thumb.setAlignment(Qt.AlignCenter)
            card_layout.addWidget(thumb)

            info_lbl = QLabel(f"<b>#{idx+1}</b> {meta.folder_name}<br>Frame: {meta.frame_id}<br><span style='color: #0969DA; font-size: 11px;'>Score: {res.similarity_score:.3f}</span>")
            card_layout.addWidget(info_lbl, 1)

            card.mousePressEvent = lambda ev, m=meta: self._on_qa_candidate_selected(m)
            self.qa_candidates_layout.addWidget(card)

        # Auto-select Rank 1
        if self.qa_candidate_results:
            self._on_qa_candidate_selected(self.qa_candidate_results[0].metadata)

    def _on_qa_candidate_selected(self, metadata):
        """Handle selection of a QA candidate keyframe"""
        self.qa_current_metadata = metadata
        self.qa_current_target_label.setText(f"🎯 Selected: {metadata.folder_name} | Frame {metadata.frame_id} ({metadata.image_name})")
        pix = self._get_image_from_unified_or_file(metadata)
        if pix and not pix.isNull():
            self.qa_zoom_viewer.set_image(pix)

    def _run_qa_ai_vision(self):
        """Analyze keyframe with OpenAI Vision to answer the question"""
        question = self.qa_question_input.text().strip()
        if not question:
            QMessageBox.warning(self, "Warning", "Vui lòng nhập câu hỏi bài toán QA.")
            return
        if not self.qa_current_metadata:
            QMessageBox.warning(self, "Warning", "Vui lòng chọn một keyframe ứng viên.")
            return

        client = getattr(getattr(self.system, 'llm_processor', None), 'openai_client', None)
        if not client:
            try:
                import openai, json
                with open('config.json', 'r', encoding='utf-8') as f:
                    cfg = json.load(f)
                key = cfg.get('openai', {}).get('api_key') or cfg.get('llm', {}).get('api_key')
                if key:
                    client = openai.OpenAI(api_key=key, timeout=30.0)
            except Exception:
                pass

        if not client:
            QMessageBox.warning(self, "Lỗi API", "OpenAI client chưa khả dụng. Vui lòng kiểm tra config.json.")
            return

        img_path = self.qa_current_metadata.file_path
        if not img_path or not os.path.exists(img_path):
            QMessageBox.warning(self, "File không tồn tại", f"Không tìm thấy file keyframe: {img_path}")
            return

        self.qa_ask_ai_btn.setEnabled(False)
        self.qa_ai_answer_box.setText("⏳ Đang gửi ảnh và câu hỏi tới AI Vision (VLM)... Vui lòng chờ vài giây.")
        self.status_bar.showMessage("AI Vision is analyzing keyframe...", 5000)

        self.qa_worker = QAVisionWorker(client, img_path, question)
        self.qa_worker.answer_ready.connect(self._on_qa_answer_ready)
        self.qa_worker.error_occurred.connect(self._on_qa_answer_error)
        self.qa_worker.start()

    def _on_qa_answer_ready(self, answer: str):
        self.qa_ask_ai_btn.setEnabled(True)
        self.qa_ai_answer_box.setText(answer)
        # Extract first line as default short answer
        first_line = answer.split("\n")[0].replace("Answer:", "").replace("Direct Answer:", "").strip()
        self.qa_final_answer_input.setText(first_line)
        self.status_bar.showMessage("✅ AI Vision đã trả lời xong!", 5000)

    def _on_qa_answer_error(self, err: str):
        self.qa_ask_ai_btn.setEnabled(True)
        self.qa_ai_answer_box.setText(f"❌ Lỗi khi phân tích AI Vision: {err}")
        self.status_bar.showMessage(f"AI Vision error: {err}", 5000)

    def _copy_qa_answer(self):
        ans = self.qa_final_answer_input.text().strip() or self.qa_ai_answer_box.toPlainText().strip()
        if ans:
            QApplication.clipboard().setText(ans)
            self.status_bar.showMessage(f"📋 Đã sao chép câu trả lời vào clipboard!", 4000)
        else:
            QMessageBox.warning(self, "Warning", "Chưa có câu trả lời để sao chép.")

    def _copy_qa_submission(self):
        if self.qa_current_metadata:
            text = f"{self.qa_current_metadata.folder_name},{self.qa_current_metadata.frame_id}"
            QApplication.clipboard().setText(text)
            self.status_bar.showMessage(f"📋 Đã sao chép '{text}' vào clipboard!", 4000)

    def _add_current_qa_to_csv(self):
        if self.qa_current_metadata and hasattr(self, 'results_widget'):
            from core import SearchResult
            res = SearchResult(metadata=self.qa_current_metadata, similarity_score=1.0, rank=len(self.results_widget.csv_results)+1)
            self.results_widget.csv_results.append(res)
            if hasattr(self.results_widget, '_add_csv_list_item'):
                self.results_widget._add_csv_list_item(res)
            self.status_bar.showMessage(f"Đã thêm {self.qa_current_metadata.image_name} vào danh sách CSV.", 4000)

